BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-22520'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='BL0065' OR source_url ~ '[?&]id=22520(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='f52380e4-20ad-43d5-9c4f-993d83abf2b3' OR slug='sam-direct-sale-office-mit-samphan-14-ban-puek-bl0065' OR description ILIKE '%BL0065%' OR (abs(latitude-13.314642445141104)<0.0001 AND abs(longitude-100.93312353033842)<0.0001 AND abs(land_area_sqm-908)<1)) THEN RAISE NOTICE 'SAM BL0065 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, custom_unit_number, title, description, sale_price, price_negotiable, land_area_sqm, total_floors, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('f52380e4-20ad-43d5-9c4f-993d83abf2b3', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'office', 'business', 'sale', 'whole_property', '32/5', 'ขายตรง SAM สำนักงาน 2 ชั้น ซอยมิตรสัมพันธ์ 14 บ้านปึก ชลบุรี 227 ตร.ว. ราคา 12.868 ล้านบาท', 'อาคารสำนักงานเลขที่ 32/5 ซอยมิตรสัมพันธ์ 14 ตำบลบ้านปึก อำเภอเมืองชลบุรี จังหวัดชลบุรี บนที่ดิน 2 แปลงติดต่อกัน เนื้อที่รวม 2 งาน 27 ตร.ว. หรือ 227 ตร.ว. (908 ตร.ม.) โฉนดเลขที่ 43334 และ 60179 ราคาประกาศขายจาก SAM 12,868,000 บาท รหัสทรัพย์ BL0065

ที่ดินรูปสี่เหลี่ยมคางหมู ด้านทิศเหนือติดถนน หน้ากว้างประมาณ 22 เมตร ลึกสุดประมาณ 48 เมตร ถนนหน้าทรัพย์คือซอยมิตรสัมพันธ์ 14 เป็นทางสาธารณประโยชน์ ผิวคอนกรีตกว้างประมาณ 8 เมตร เขตทางประมาณ 10 เมตร ต้นทางระบุเขตผังเมืองสีส้ม อยู่ในย่านที่อยู่อาศัย

รายการสิ่งปลูกสร้างตามทะเบียนที่ SAM รับโอนมี 2 รายการ ได้แก่ โรงจอดรถ และสำนักงานความสูง 2 ชั้น เลขที่ 32/5 ส่วนการสำรวจสภาพทรัพย์ระบุ 4 รายการ ได้แก่ อาคารพักอาศัยพร้อมสำนักงาน 2 ชั้น, อาคารโรงงาน 2 ชั้น, โรงจอดรถ และป้อมยาม

ข้อมูลสำคัญ: SAM ระบุว่าจะโอนให้ผู้ซื้อตามรายการสิ่งปลูกสร้างที่จดทะเบียนรับโอนเท่านั้น อาคารโรงงานและป้อมยามที่ปรากฏในการสำรวจจึงต้องตรวจสอบสิทธิและรายการที่จะได้รับโอนก่อนเสนอซื้อ รวมถึงทะเบียนอาคาร แบบแปลน ใบอนุญาต และความสอดคล้องกับสภาพจริง การจัดหมวดประกาศนี้ยึดสำนักงานตามต้นทาง ไม่ได้ยืนยันใบอนุญาตประกอบกิจการโรงงาน

SAM ระบุว่าสาธารณูปโภคครบครันและเดินทางสะดวก แต่ไม่ได้ระบุกำลังไฟฟ้าหรือรายละเอียดระบบภายใน สถานที่ใกล้เคียงที่ต้นทางระบุ ได้แก่ วัดใหม่เกตุงาม โรงเรียนวัดใหม่เกตุงาม และโรงเรียนวัดเตาปูน

การเดินทางมี 2 ทางตาม SAM: จากถนนสุขุมวิท (ทล.3) มุ่งหน้าพัทยา ผ่านบิ๊กซี ชลบุรี 2 ถึงแยกอ่างศิลา เลี้ยวขวาเข้าถนนหมายเลข 3134 ผ่านโรงพยาบาลเอกชล 2 แล้วเลี้ยวซ้ายเข้าซอยมิตรสัมพันธ์ 14 ผ่านโรงเรียนวัดเตาปูน ทรัพย์อยู่ซ้ายมือ หรือเข้าจากถนนมิตรสัมพันธ์สู่ซอยมิตรสัมพันธ์ 14 ประมาณ 200 เมตร ทรัพย์อยู่ขวามือ

หน้า SAM แสดงสถานะซื้อตรงและราคาข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส BL0065 เพื่อยืนยันสถานะพร้อมขาย ราคา การนัดชม และเงื่อนไขล่าสุด

ใช้พิกัดผู้ดูแล 13.314642445141104, 100.93312353033842 ซึ่งใกล้เคียงหมุด SAM ภาพต้นทางแสดงวันที่ 26 มกราคม 2568 เป็นภาพภายนอก บริเวณอาคาร ทางเข้า พื้นที่หลังคาคลุม ผังแปลง ผังอาคาร และแผนที่ ต้นทางไม่มีภาพภายในห้อง และไม่ระบุพื้นที่ใช้สอยรวม จำนวนห้องน้ำ จำนวนที่จอดรถ อายุอาคาร สถานะผู้ครอบครอง หรือใบอนุญาตกิจการ ผู้สนใจควรนัดตรวจสภาพปัจจุบันกับ SAM', 12868000, false, 908, 2, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, '32/5 ซอยมิตรสัมพันธ์ 14', 'เข้าจากถนนมิตรสัมพันธ์ประมาณ 200 เมตร', 'ซอยมิตรสัมพันธ์ 14', 13.314642445141104, 100.93312353033842, 'ชลบุรี', 'เมืองชลบุรี', 'บ้านปึก', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-direct-sale-office-mit-samphan-14-ban-puek-bl0065') RETURNING id INTO property_listing_id;
