INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=22520&keyref=6007623', 'BL0065', now(), 'Official SAM source captured 2026-09-11. Direct purchase THB 12,868,000, 227 sq.wah. Registered garage and two-storey office versus surveyed residential/office, factory, garage and guardhouse. Registered-only transfer disclosed; no factory licence inferred. Nine source exterior/covered-area/access/plan images retained with source dates 2025-01-26; no retouching. All-status code/page/deed/area/nearby-coordinate duplicate search found no matches. Shared keyref is not unique identity.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: 2-Storey Office on 227 Sq.Wah, Mit Samphan 14, THB 12.868M', 'Office building numbered 32/5 in Soi Mit Samphan 14, Ban Puek, Mueang Chon Buri, Chon Buri. Two adjoining plots, deeds 43334 and 60179, total 2 ngan 27 sq.wah, equivalent to 227 sq.wah or 908 sq.m. SAM announced price THB 12,868,000; asset BL0065.

The trapezoidal site has approximately 22 metres of northern road frontage and a maximum depth of approximately 48 metres. Soi Mit Samphan 14 is described as a public concrete road approximately eight metres wide within a ten-metre right of way. SAM reports orange planning zoning and residential surroundings.

Registered acquired structures comprise a garage and a two-storey office numbered 32/5. The physical survey lists four structures: a two-storey residential/office building, a two-storey factory building, a garage and a guardhouse. SAM states that transfer follows only its registered acquisition inventory. Verify rights to the surveyed factory and guardhouse, building registration, plans, permits and the exact transfer inventory. This office listing does not confirm a factory operating licence.

SAM describes available utilities and convenient transport but gives no electrical capacity or internal system specifications. Nearby source-listed places include Wat Mai Ket Ngam, Wat Mai Ket Ngam School and Wat Tao Pun School.

From Sukhumvit Road (Highway 3) toward Pattaya, pass Big C Chonburi 2 and turn right at Ang Sila junction onto Highway 3134. Pass Aikchol 2 Hospital and turn left into Soi Mit Samphan 14, passing Wat Tao Pun School; the site is on the left. Alternatively, enter Soi Mit Samphan 14 from Mit Samphan Road for approximately 200 metres; the site is on the right.

SAM showed direct-purchase status and this price on 11 September 2026. Contact 02-686-1888, sales@sam.or.th or LINE @samline, quoting BL0065, to confirm availability, price, viewing and terms. Administrator coordinates are used.

Source images display 26 January 2025 and show exterior building areas, access, covered areas and plot/building plans. No room-interior photographs, total usable area, bathroom count, parking capacity, building age, occupancy status or operating permits are published. Arrange a current inspection.', '32/5, Soi Mit Samphan 14', 'Approximately 200 metres from Mit Samphan Road', 'Soi Mit Samphan 14', 'Ban Puek', 'Mueang Chon Buri', 'Chon Buri', 'SAM Office in Mit Samphan 14 — THB 12.868M', 'SAM BL0065: two-storey office on 227 sq.wah in Ban Puek. Registered and surveyed building inventories differ; see transfer details.', 'published', 'ai_assisted', now(), 'sam direct sale: 2-storey office on 227 sq.wah, mit samphan 14, thb 12.868m office building numbered 32/5 in soi mit samphan 14, ban puek, mueang chon buri, chon buri. two adjoining plots, deeds 43334 and 60179, total 2 ngan 27 sq.wah, equivalent to 227 sq.wah or 908 sq.m. sam announced price thb 12,868,000; asset bl0065.

the trapezoidal site has approximately 22 metres of northern road frontage and a maximum depth of approximately 48 metres. soi mit samphan 14 is described as a public concrete road approximately eight metres wide within a ten-metre right of way. sam reports orange planning zoning and residential surroundings.

registered acquired structures comprise a garage and a two-storey office numbered 32/5. the physical survey lists four structures: a two-storey residential/office building, a two-storey factory building, a garage and a guardhouse. sam states that transfer follows only its registered acquisition inventory. verify rights to the surveyed factory and guardhouse, building registration, plans, permits and the exact transfer inventory. this office listing does not confirm a factory operating licence.

sam describes available utilities and convenient transport but gives no electrical capacity or internal system specifications. nearby source-listed places include wat mai ket ngam, wat mai ket ngam school and wat tao pun school.

